const raw = $json.body ?? $json;
const result = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!result || typeof result !== 'object') {
  throw new Error('Validation response is not a JSON object');
}
if (result.validation) {
  result.validation.passed = result.validation.passed === true || String(result.validation.passed).trim().toLowerCase() === 'true';
}
return [{ json: result }];

const result = $json;
const passed = result.validation?.passed === true || String(result.validation?.passed).toLowerCase() === 'true';
const manualApproval = result.manual_approval === true || String(result.manual_approval).toLowerCase() === 'true';
if (!passed && !manualApproval) {
  throw new Error('Approval guard blocked: validation failed and manual approval was not requested');
}
if (!result.job_id || !result.draft) {
  throw new Error('Approval guard blocked: job_id and draft required');
}
return [{ json: result }];

const result = $json;
const revision_attempt = Number(result.revision_attempt ?? 0) + 1;
return [{ json: { ...result, revision_attempt } }];

const result = $json;
return [{ json: {
  job_id: result.job_id,
  status: 'awaiting_approval',
  approval_id: result.approval_id ?? null,
  approval_status: result.approval_status ?? 'pending',
  revision_attempt: result.revision_attempt ?? 0,
  outline: result.outline ?? null,
  draft: result.draft ?? null,
  validation: result.validation ?? null,
  sources: result.sources ?? [],
  next: 'human_approval'
} }];

const result = $json;
return [{ json: {
  ...result,
  status: 'awaiting_approval',
  manual_approval: true,
  revision_attempt: result.revision_attempt ?? 0,
  error_code: 'manual_review_required',
  error_message: 'Automatic validation remained unsuccessful after two revisions. Human decision required.'
} }];
